'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const E=window.UnixEngine,L=window.LESSONS,R=window.REVIEWS,STORE='unix-lab-progress-v1';
const UNIT_TITLES={w01:'강의 소개와 Linux',w02:'Linux 명령어·vi·Makefile',w06:'파일 시스템과 파일 입출력',w09:'표준 입출력'};
const unitCount=u=>L.filter(x=>x.unit===u).length;
let saved={done:[],answers:{},notes:{}},persist=true;
try{const p=JSON.parse(localStorage.getItem(STORE)||'null');if(p&&Array.isArray(p.done)&&p.answers){saved={...saved,...p};}}catch(e){persist=false;}
let unit='w06',page=45,tab='learn',filter='all',timer=null,simName='independent',simStep=0,simText='ABCDEFGH',structureStep=0,allocation='chain',cacheStage=0;
const validId=id=>L.some(x=>x.id===id);
function lesson(){return L.find(x=>x.unit===unit&&x.page===page);}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3000);}
function save(){saved.last={unit,page,tab};try{localStorage.setItem(STORE,JSON.stringify(saved));}catch(e){persist=false;}updateProgress();}
function updateProgress(){let done=saved.done.filter(validId).length,answers=Object.entries(saved.answers).filter(([k])=>validId(k)),correct=answers.filter(([,v])=>v.correct).length;$('#progress-label').textContent=`${done} / ${L.length}`;$('#progress-bar').max=L.length;$('#progress-bar').value=done;$('#quiz-summary').textContent=`퀴즈 ${answers.length}/${L.length} · 정답 ${correct} · 오답 ${answers.length-correct}`;$('#wrong-count').textContent=answers.length-correct;$('#storage-note').textContent=persist?'이 브라우저에 자동 저장 · 기기 간 공유 안 됨':'자동 저장 불가 · 기록 내보내기를 사용하세요';}
function optionsFor(l){const a=l.quiz.options.map((text,i)=>({text,correct:i===0}));const rotate=(l.page+(l.unit==='w06'?2:0))%4;return a.slice(rotate).concat(a.slice(0,rotate));}
function pageReviews(l){return R.filter(r=>r.id===l.id);}
function stop(){if(timer){clearInterval(timer);timer=null;}}
function defaultScenario(){if(unit==='w01')return 'basic';if(page>=55&&page<=59)return page===59?'redirect':'duplicate';if(page>=43&&page<=45)return 'independent';if(page>=46&&page<=48)return 'processes';if(page===49||page===53||page===54)return 'position';if(page===38||page===39||page===33)return 'partial';if(page===41)return 'append';return 'basic';}
function go(u,n,t=tab){stop();unit=u;page=n;tab=t;structureStep=0;simName=defaultScenario();simStep=0;cacheStage=0;document.body.classList.remove('menu-open');$('#menu').setAttribute('aria-expanded','false');render();window.scrollTo({top:0,behavior:'instant'});}
function renderNav(){const term=$('#search').value.trim().toLowerCase();let list=L.filter(l=>l.unit===unit);$('#pages').innerHTML=list.filter(l=>(!term||String(l.page)===term||`${l.title} ${l.original} ${l.explain.join(' ')}`.toLowerCase().includes(term))&&(filter!=='wrong'||saved.answers[l.id]&&!saved.answers[l.id].correct)&&(filter!=='review'||pageReviews(l).length)).map(l=>`<button data-page="${l.page}" class="${page===l.page?'active':''}" ${page===l.page?'aria-current="page"':''}><span class="pnum">${String(l.page).padStart(2,'0')}</span><span class="ptitle">${esc(l.title)}</span><span class="status ${saved.answers[l.id]&&!saved.answers[l.id].correct?'wrong':''}">${saved.answers[l.id]&&!saved.answers[l.id].correct?'!':saved.done.includes(l.id)?'✓':pageReviews(l).length?'·':''}</span></button>`).join('')||'<p class="empty">해당하는 페이지가 없습니다.</p>';$$('#pages button').forEach(b=>b.onclick=()=>go(unit,+b.dataset.page));$$('[data-unit]').forEach(b=>b.classList.toggle('active',b.dataset.unit===unit));$('#unit-title').textContent=`${unit}. ${UNIT_TITLES[unit]}`;['all','wrong','review'].forEach(f=>$(`#${f}-filter`).classList.toggle('active',filter===f));}
function render(){const l=lesson();document.title=`${unit} ${page}쪽 · ${l.title} | UNIX LAB`;$('#title').textContent=l.title;$('#lead').textContent=l.explain[0];$('#breadcrumb').textContent=`${unit}. ${UNIT_TITLES[unit]}  ›  ${String(page).padStart(2,'0')}쪽`;$('#jump').innerHTML=L.filter(x=>x.unit===unit).map(x=>`<option value="${x.page}" ${x.page===page?'selected':''}>${unit} · ${x.page} / ${unitCount(unit)}</option>`).join('');$('#prev').disabled=page===1&&unit==='w01';$('#next').disabled=$('#next-bottom').disabled=L.indexOf(l)===L.length-1;$('#complete').textContent=saved.done.includes(l.id)?'✓ 학습 완료':'학습 완료 표시';$('#complete').classList.toggle('done',saved.done.includes(l.id));$('#review-count').textContent=pageReviews(l).length||'';$$('[data-tab]').forEach(b=>{b.setAttribute('aria-selected',b.dataset.tab===tab);b.tabIndex=b.dataset.tab===tab?0:-1;});renderNav();renderPanel();save();history.replaceState(null,'',`#${unit}/${page}/${tab}`);}
function substantive(l){return !!l.quiz&&!["w01-1","w01-2","w01-3","w01-20","w02-1","w06-1","w06-19","w06-20"].includes(l.id)&&!/표지|참고문헌|목차/.test(l.title);}
function quickQuiz(l){if(!substantive(l))return "";return `<div class="quick-quiz"><div><h3>이 페이지를 이해했나요?</h3>${esc(l.quiz.question)}</div><button class="primary" data-action="quiz">퀴즈 풀기 →</button></div>`;}
function miniSource(l){if(l.unit==='w09')return '<div><h3>강의자료 · w09 '+l.page+'쪽</h3><button type="button" data-w09-source>PDF 원문 열기</button></div>';return `<div><h3>강의자료 · ${unit} ${page}쪽</h3><img class="page-image" src="${l.image}" alt="${unit} ${page}쪽 원문: ${esc(l.title)}" data-zoom="${l.image}"><div class="source-caption"><span>이미지를 누르면 확대됩니다</span><button data-action="original">원문 전체 보기</button></div>${pageReviews(l).length?`<div class="note warning">이 페이지에는 검토 항목 ${pageReviews(l).length}개가 있습니다. <button data-action="review">원문·검증 설명 비교</button></div>`:''}</div>`;}
function renderPanel(){const l=lesson();document.querySelector('[data-tab=quiz]').hidden=!substantive(l);if(tab==='quiz'&&!substantive(l))tab='learn';if(unit==='w09'&&tab==='original'){$('#panel').innerHTML=miniSource(l);}
 else if(tab==='learn'){
 const isFD=unit==='w06'&&((page>=17&&page<=18)||(page>=43&&page<=48)||(page>=55&&page<=59));
 $('#panel').innerHTML=(isFD?labHTML(true):'')+`<div class="lesson-grid ${isFD?'section-rule':''}"><article><h2>${isFD?'더 자세히 알아보기':'핵심을 연결해서 읽기'}</h2><div class="explanation">${l.explain.map(p=>`<p>${esc(p)}</p>`).join('')}</div>${deepHTML(l)}${!isFD?(unit==='w02'?'<div class="concept-callout">이 주제의 동작을 직접 확인해 보세요. <button data-action="lab">2주차 실험실 열기 →</button></div>':unit==='w09'?'<div class="concept-callout"><button data-action="lab">표준 입출력 실험 열기 →</button></div>':structureHTML()):''}<div class="note">교재 해설은 원문을 이해하기 위한 설명입니다. 교수의 구두 발언이나 시험 정답을 재현한 것이 아닙니다.${[1,19,20].includes(page)&&unit==='w06'?' 이 페이지는 구간 표지이므로 새로운 함수 명세를 덧붙이지 않았습니다.':''}</div>${quickQuiz(l)}</article>${miniSource(l)}</div>`;
 }else if(tab==='lab'){$('#panel').innerHTML=labView();}
 else if(tab==='quiz')renderQuiz();
 else if(tab==='review')renderReviews();
 else $('#panel').innerHTML=`<h2>강의자료 원문 · ${unit} ${page}쪽</h2><p class="lab-note">도표·함수 선언·코드의 배치는 원문 이미지로 확인하세요. 오른쪽은 검색과 대조용 추출 텍스트이며 그림 안의 정보가 빠질 수 있습니다.</p><div class="original-grid"><div><img class="page-image" src="${l.image}" data-zoom="${l.image}" alt="${esc(l.title)} 원문 확대"><p class="source-caption"><a href="original/${unit}.pdf#page=${page}" target="_blank" rel="noopener">원본 PDF에서 이 페이지 열기</a></p></div><pre class="original-text">${esc(l.original)}</pre></div>`;
 bindPanel();}
function bindPanel(){const source=$('[data-w09-source]');if(source)source.onclick=()=>window.StudyLibrary.openW09(page);window.W09Lab?.bind();$$('[data-action]').forEach(b=>b.onclick=()=>{stop();tab=b.dataset.action;render();});$$('[data-zoom]').forEach(im=>im.onclick=()=>{$('#full-image').src=im.dataset.zoom;$('#image-dialog').showModal();});bindLab();bindStructure();window.W02.bind();}
function labHTML(compact=false){const sc=E.scenarios[simName],s=E.run(simName,simStep,simText);const entries=Object.entries(s.fds).filter(([,v])=>s.files[v]);let refs={};entries.forEach(([,v])=>refs[v]=(refs[v]||0)+1);const arrow=`<svg class="edge" viewBox="0 0 26 180" aria-hidden="true"><path d="M0 90 H22 L17 85 M22 90 L17 95"/></svg>`;
 return `<div class="lab-top"><label>시나리오<select id="scenario">${Object.entries(E.scenarios).map(([k,v])=>`<option value="${k}" ${simName===k?'selected':''}>${v.name}</option>`).join('')}</select></label><label>초기 파일 내용 · ASCII, 최대 16바이트<input id="initial-data" value="${esc(simText)}" maxlength="16" autocomplete="off"></label></div><div class="lab-grid"><div class="panel"><div class="panel-title"><span>실행할 코드</span><span>C / POSIX 모델</span></div><div class="code-lines">${sc.steps.map((o,i)=>`<div class="code-line ${i===simStep-1?'current':i<simStep?'past':''}"><span class="line-num">${i+1}</span><span>${esc(E.code(o))}</span></div>`).join('')}</div><div class="panel-body"><p class="lab-note">${esc(sc.pages)}<br>예측 연습: 다음 줄 실행 전 offset과 반환값을 말해 보세요.</p><div class="buffer">buf = ${esc(JSON.stringify(s.buffer))}<br>※ 화면의 \\u0000은 0 바이트를 뜻합니다.</div></div></div><div class="panel"><div class="panel-title"><span>동작 과정 시각화</span><span>${simStep} / ${sc.steps.length} 단계</span></div><div class="panel-body"><div class="diagram"><div class="col"><h3>프로세스 FD</h3><small>프로세스별 참조</small>${['P1:0','P1:1','P1:2'].filter(k=>typeof s.fds[k]==='string'&&!s.files[s.fds[k]]).map(k=>`<div class="node">${k.split(':')[1]} · ${s.fds[k]}</div>`).join('')}${entries.map(([k,v])=>`<div class="node ${v===s.active?'changed':''}"><b>${k.replace(':',' · fd ')} → ${v}</b>열린 항목 참조</div>`).join('')}</div>${arrow}<div class="col"><h3>열린 파일</h3><small>offset / 상태</small>${Object.entries(s.files).filter(([k])=>refs[k]).map(([k,f])=>`<div class="node ${k===s.active?'changed':''}"><b>항목 ${k} · O_${f.mode}</b>offset <strong>${f.offset}</strong><br>fd 참조 ${refs[k]}개<br>inode → 101</div>`).join('')||'<div class="node">열린 파일 없음</div>'}</div>${arrow}<div class="col"><h3>inode</h3><small>파일의 메타데이터</small><div class="node"><b>#101 · test.txt</b>파일 크기 ${s.data.length}<br>파일 내용은 아래에 표시<br>이름은 디렉토리와 연결</div></div></div><div class="data-strip" aria-label="파일 데이터 바이트와 위치">${s.data.map((b,i)=>`<span class="byte ${Object.values(s.files).some(f=>f===s.files[s.active]&&f.offset===i)?'cursor':''}">${b==='\0'?'00':esc(b)}<small>${i}</small></span>`).join('')}<span class="byte ${s.files[s.active]?.offset===s.data.length?'cursor':''}">EOF<small>${s.data.length}</small></span></div><div class="returns"><span>return = <b>${esc(s.ret)}</b></span><span>errno = <b>${esc(s.errno)}</b></span></div><div class="narration" aria-live="polite">${esc(s.note)}<div class="sim-controls"><span class="step-label">${simStep===0?'시작 전':simStep===sc.steps.length?'마지막 단계':'단계 '+simStep}</span><button id="sim-reset">초기화</button><button id="sim-prev" ${simStep===0?'disabled':''}>이전 단계</button><button id="sim-play" ${simStep===sc.steps.length?'disabled':''}>${timer?'일시 정지':'자동 재생'}</button><button class="primary" id="sim-next" ${simStep===sc.steps.length?'disabled':''}>다음 단계</button></div></div></div></div></div><p class="lab-note">교육용 결정적 시뮬레이션입니다. 실제 C 컴파일·커널 실행은 하지 않습니다. 일반 파일·ASCII 바이트·성공한 open을 기본 가정하고 명시된 오류와 부분 전송만 모형화합니다. fd 0·1·2는 미리 열려 있습니다. inode 번호와 열린 항목 이름은 설명용 값입니다. 초록 연결선은 참조 관계를 뜻합니다.</p>${compact?'':`<div class="concept-callout">open 2회 → 열린 파일 항목 2개 → 독립 offset<br>dup → 같은 열린 파일 항목 참조 → 공유 offset</div>`}`;}
function labView(){if(unit==='w09')return window.W09Lab.html(page);if(unit==='w02')return window.W02.html(page);if(unit==='w01')return `<h2>사용자 공간에서 하드웨어까지</h2>${structureHTML('kernel')}<div class="section-rule"><h2>파일 입출력 실험실</h2><p class="lab-note">이 실험은 w06 25~59쪽의 함수 개념을 학습하는 공통 실험입니다. 현재 w01 페이지의 원문 코드가 아닙니다.</p>${labHTML()}</div>`;if(page>=60&&page<=67)return multiplexHTML();if(page>=68)return cacheHTML();if(page>=3&&page<=16)return `<h2>저장 구조 실험</h2>${structureHTML()}<div class="section-rule"><h2>파일 입출력 실험실</h2><p class="lab-note">아래 코드는 w06 후반부 함수 개념의 공통 축소 예제입니다.</p>${labHTML()}</div>`;return labHTML();}
function bindLab(){if($('#scenario'))$('#scenario').onchange=e=>{stop();simName=e.target.value;simStep=0;renderPanel();};if($('#initial-data'))$('#initial-data').onchange=e=>{const text=e.target.value;if(!/^[\x20-\x7e]{0,16}$/.test(text)){e.target.value=simText;toast('공백을 포함한 ASCII 문자 16자 이내로 입력하세요.');return;}stop();simText=text;simStep=0;renderPanel();};if($('#sim-next'))$('#sim-next').onclick=()=>{simStep=Math.min(simStep+1,E.scenarios[simName].steps.length);if(simStep===E.scenarios[simName].steps.length)stop();renderPanel();};if($('#sim-prev'))$('#sim-prev').onclick=()=>{stop();simStep=Math.max(0,simStep-1);renderPanel();};if($('#sim-reset'))$('#sim-reset').onclick=()=>{stop();simStep=0;renderPanel();};if($('#sim-play'))$('#sim-play').onclick=()=>{if(timer){stop();renderPanel();return;}timer=setInterval(()=>{simStep++;if(simStep>=E.scenarios[simName].steps.length)stop();renderPanel();},1500);renderPanel();};}
function structureHTML(force){let type=force||(unit==='w01'?'kernel':page<=4?'mount':page<=10?'blocks':page<=16?'inode':'kernel');if(type==='kernel'){const names=['사용자 프로그램','시스템 호출 경계','Linux 커널','하드웨어'];return `<div class="structure" data-structure="kernel"><h3>호출 경로 따라가기</h3><div class="flow-row">${names.map((n,i)=>`${i?'<span class="flow-arrow" aria-hidden="true">→</span>':''}<div class="flow-box ${structureStep===i?'lit':''}">${n}<small>${['에디터 · 셸 · 응용 프로그램','open · read · write','파일 · 메모리 · 프로세스 관리','CPU · 메모리 · 장치'][i]}</small></div>`).join('')}</div><p class="lab-note">${['프로그램이 파일 읽기 같은 작업을 요청합니다.','시스템 호출 인터페이스로 커널 서비스를 요청합니다.','커널이 권한·파일 시스템·캐시·장치 처리를 관리합니다.','필요한 장치 처리를 거쳐 결과가 돌아옵니다.'][structureStep%4]} 개념적인 계층 흐름이며 매 호출이 물리 디스크에 도달한다는 뜻은 아닙니다.</p><button id="structure-next">다음 경로 →</button></div>`;}
if(type==='mount')return `<div class="structure" data-structure="mount"><h3>마운트 전과 후</h3><div class="flow-row"><div class="flow-box">루트 /<small>etc · usr · home</small></div><span class="flow-arrow">${structureStep%2?'→':'+'}</span><div class="flow-box ${structureStep%2?'lit':''}">${structureStep%2?'/home/user1 · /home/user2':'별도 파일 시스템 /'}<small>${structureStep%2?'home 아래로 접목됨':'user1 · user2'}</small></div></div><p class="lab-note">${structureStep%2?'같은 경로 트리에서 접근합니다. 파일 내용을 복사한 것이 아닙니다.':'두 번째 파일 시스템을 기존 디렉토리 home에 연결하기 전입니다.'}</p><button id="structure-next">${structureStep%2?'마운트 이전 보기':'마운트하기'}</button></div>`;
if(type==='blocks'){let used=[0,2,3,4,7,8,11,12,17],chosen=allocation==='sequential'?[13,14,15,16]:[1,5,6,9];return `<div class="structure" data-structure="blocks"><h3>14KB 파일 / 4KB 블록</h3><div class="structure-controls"><button data-allocation="sequential">연속 할당</button><button data-allocation="chain">블록 체인</button><button data-allocation="index">인덱스 블록</button></div><div class="block-grid">${Array.from({length:18},(_,i)=>`<div class="block ${used.includes(i)?'used':''} ${chosen.slice(0,structureStep).includes(i)||allocation==='index'&&i===10&&structureStep?'allocated':''}">${i}${allocation==='index'&&i===10?'<small> index</small>':''}</div>`).join('')}</div><p class="lab-note">${allocation==='sequential'?'연속된 13~16번에 배치하는 교재용 예시입니다.':allocation==='chain'?'파일 순서: 1 → 5 → 6 → 9. 연결 정보를 따라갑니다.':'10번 인덱스 블록이 1·5·6·9번을 가리킵니다. 인덱스 블록 비용은 데이터 블록 4개와 별도입니다.'} 데이터 블록 ${Math.min(structureStep,4)}/4개 할당. 마지막 블록의 2KB는 사용하지 않습니다.</p><button id="structure-next">${structureStep>=4?'다시 보기':'블록 하나 할당 →'}</button></div>`;}
return `<div class="structure" data-structure="inode"><h3>이름에서 데이터까지</h3><div class="flow-row">${['디렉토리 항목','inode #101',structureStep%2?'간접 주소 블록':'직접 블록 포인터','데이터 블록'].map((x,i)=>`${i?'<span class="flow-arrow">→</span>':''}<div class="flow-box ${structureStep%4===i?'lit':''}">${x}<small>${['test.txt → 101','유형 · 권한 · 크기','블록 주소','파일 바이트열'][i]}</small></div>`).join('')}</div><p class="lab-note">파일 이름과 inode의 연결, 메타데이터와 실제 내용의 위치를 구분합니다. 직접·간접 포인터를 설명하는 단순화된 모형입니다.</p><button id="structure-next">주소 경로 전환 →</button></div>`;}
function multiplexHTML(){return `<h2>준비 상태를 기다리는 select / poll</h2><p>준비 상태를 바꾸고 대기 결과를 비교해 보세요. 감시 fd는 0과 7입니다. 두 fd는 서로 다른 집합에 중복 등록하지 않는 단순 예시입니다.</p><div class="ready-row"><label><input id="ready-in" type="checkbox"> fd 0 읽기 준비</label><label><input id="ready-out" type="checkbox" ${page===66?'checked':''}> fd 7 쓰기 준비</label><label><input id="ready-error" type="checkbox"> 대기 호출 EINTR</label></div><div class="structure-controls"><button id="wait-select">select 실행</button><button id="wait-poll">poll 실행</button></div><div class="ready-output" id="ready-result" role="status">설정 후 실행하세요. 실제 시간 대기를 생략한 준비 상태 모델입니다.</div><div class="concept-callout">select: nfds = maxfd + 1 = 8 / fd_set은 결과로 수정<br>poll: nfds = 배열 원소 수 = 2 / events 입력 · revents 결과<br>pselect·ppoll: timespec과 시그널 마스크를 사용</div><p class="lab-note">프로세스 시작, FIFO open 대기와 시그널 전달 타이밍 전체를 재현하지 않습니다. 선택한 상태에서 시스템 호출 결과를 예측하는 실험입니다.</p>${quickQuiz(lesson())}`;}
function cacheHTML(){const n=cacheStage%4;return `<h2>페이지 캐시와 저장장치</h2><p>아래 데이터 이동은 원문의 cache와 writeback 개념을 단순화한 실험입니다.</p><div class="flow-row section-rule"><div class="flow-box ${n===0?'lit':''}">사용자 버퍼<small>변경할 데이터 X</small></div><span class="flow-arrow">→</span><div class="flow-box ${n===1||n===2?'lit':''}">페이지 캐시<small>${n===0?'아직 변경 전':n<3?'dirty page':'clean page'}</small></div><span class="flow-arrow">→</span><div class="flow-box ${n===3?'lit':''}">저장장치<small>${n===3?'X 반영 완료':'이전 데이터'}</small></div></div><div class="cache-line"><div class="cache-cell ${n===1||n===2?'dirty':'clean'}">페이지 A</div><div class="cache-cell clean">페이지 B</div><div class="cache-cell clean">페이지 C</div></div><p class="narration">${['변경 전: 사용자 버퍼의 내용을 아직 write하지 않았습니다.','write가 캐시를 변경했습니다. 반환 성공이 전원 장애 후 영속성을 뜻하지는 않습니다.','writeback 전 전원이 꺼지면 저장되지 않은 최근 변경이 유실될 수 있습니다.','writeback 또는 적절한 동기화가 완료된 상태를 표시합니다. 캐시 내용과 저장장치가 맞아집니다.'][n]}</p><div class="structure-controls"><button id="cache-next">${n===3?'처음부터':'다음 상태 →'}</button><button id="cache-sync">fsync 완료로 이동</button></div><div class="concept-callout">fsync: 데이터 + 관련 메타데이터<br>fdatasync: 데이터 + 이후 읽기에 필요한 메타데이터<br>fflush: stdio의 사용자 버퍼를 내보냄 / 영구 저장과 구분</div>${quickQuiz(lesson())}`;}
function bindStructure(){if($('#structure-next'))$('#structure-next').onclick=()=>{const t=$('[data-structure]').dataset.structure;structureStep=t==='blocks'?(structureStep+1)%5:t==='mount'?(structureStep+1)%2:(structureStep+1)%4;renderPanel();};$$('[data-allocation]').forEach(b=>b.onclick=()=>{allocation=b.dataset.allocation;structureStep=0;renderPanel();});if($('#cache-next'))$('#cache-next').onclick=()=>{cacheStage++;renderPanel();};if($('#cache-sync'))$('#cache-sync').onclick=()=>{cacheStage=3;renderPanel();};['select','poll'].forEach(kind=>{const b=$('#wait-'+kind);if(b)b.onclick=()=>{let a=$('#ready-in').checked,c=$('#ready-out').checked,error=$('#ready-error').checked;$('#ready-result').textContent=error?`${kind}: return = -1, errno = EINTR`:kind==='select'?`select(8, ...) → return = ${+a + +c}\n${a?'fd 0: 읽기 준비':''}${c?'\nfd 7: 쓰기 준비':''}${!a&&!c?'0: timeout · 준비된 fd 없음':''}`:`poll(fds, 2, 5000) → return = ${+a + +c}\nfds[0].revents = ${a?'POLLIN':'0'}\nfds[1].revents = ${c?'POLLOUT':'0'}${!a&&!c?'\n0: timeout':''}`;};});}
function renderQuiz(){const l=lesson(),a=saved.answers[l.id],opts=optionsFor(l);$('#panel').innerHTML=`<article class="quiz"><h2>${unit} ${page}쪽 · 확인 퀴즈</h2><p class="lab-note">선택 후 채점하면 정답과 이유를 확인할 수 있습니다. 틀린 문제는 왼쪽 오답 목록에 모입니다.</p><form id="quiz-form"><fieldset><legend class="question">${esc(l.quiz.question)}</legend>${opts.map((o,i)=>`<label class="answer"><input type="radio" name="answer" value="${i}" ${a&&a.choice===i?'checked':''}><span>${esc(o.text)}</span></label>`).join('')}</fieldset><div class="quiz-actions"><button type="submit" class="primary">정답 확인</button><button type="button" id="quiz-retry">다시 풀기</button>${a?'<button type="button" id="quiz-next-wrong">다음 오답 복습</button><button type="button" id="quiz-clear">채점 기록 지우기</button>':''}</div></form><div id="quiz-feedback">${a?feedback(l,a):''}</div><div class="quiz-history">${a?`시도 ${a.attempts}회 · 최근 결과 ${a.correct?'정답':'오답'} · 정답을 맞히면 현재 오답 목록에서 제외됩니다.`:'아직 채점하지 않았습니다.'}</div><div class="section-rule"><h3>기억을 꺼내는 연습</h3><p class="lab-note">답을 보기 전에 이 페이지에서 구분해야 하는 개념을 자신의 말로 적어 보세요. 메모는 이 브라우저에 저장됩니다.</p><label for="study-note" class="sr-only">내 학습 메모</label><textarea id="study-note" rows="5" style="width:100%;font:inherit;font-size:18px;padding:15px;border:1px solid var(--line);border-radius:5px" placeholder="예: inode 공유와 offset 공유는 왜 다른가?">${esc(saved.notes[l.id]||'')}</textarea></div></article>`;
$('#quiz-form').onsubmit=e=>{e.preventDefault();const v=new FormData(e.target).get('answer');if(v===null){toast('답을 하나 선택하세요.');return;}const n=+v,correct=opts[n].correct;saved.answers[l.id]={choice:n,correct,attempts:(saved.answers[l.id]?.attempts||0)+1};if(correct&&!saved.done.includes(l.id))saved.done.push(l.id);save();renderNav();renderQuiz();bindPanel();};$('#quiz-retry').onclick=()=>{$$('#quiz-form input').forEach(x=>x.checked=false);$('#quiz-feedback').innerHTML='';toast('답을 다시 선택해 채점하세요. 기존 기록은 새 채점 때 갱신됩니다.');};if($('#quiz-next-wrong'))$('#quiz-next-wrong').onclick=()=>{const wrong=L.filter(x=>saved.answers[x.id]&&!saved.answers[x.id].correct);let next=wrong.find(x=>L.indexOf(x)>L.indexOf(l))||wrong[0];if(next)go(next.unit,next.page,'quiz');else toast('복습할 오답이 없습니다.');};if($('#quiz-clear'))$('#quiz-clear').onclick=()=>{delete saved.answers[l.id];save();renderNav();renderQuiz();bindPanel();};$('#study-note').oninput=e=>{saved.notes[l.id]=e.target.value;save();};}
function feedback(l,a){return `<div class="feedback ${a.correct?'':'wrong'}" role="status"><h3>${a.correct?'정답입니다.':'다시 확인해 보세요.'}</h3><b>정답: ${esc(l.quiz.options[0])}</b><p>${esc(l.quiz.why)}</p><button data-action="learn">개념 다시 읽기</button>${pageReviews(l).length?'<button data-action="review">자료 검토 확인</button>':''}</div>`;}
function renderReviews(){const l=lesson(),reviews=pageReviews(l);$('#panel').innerHTML=`<h2>원문과 검증 설명을 구분하기</h2><p class="lab-note">범위는 w01·w02·w06·w09 강의자료 총 ${L.length}쪽입니다. 외부 문서는 오류 검증에만 사용했습니다. 아래 설명은 강의에서 정정된 내용을 재현한 것이 아닙니다. 오류 후보가 없는 페이지도 오류가 없음을 보증하지는 않습니다.</p>${reviews.length?reviews.map(r=>`<article class="review-item"><h3>${esc(r.kind)}</h3><div class="review-columns"><div><span class="review-label">강의자료 원문 발췌</span><blockquote>${esc(r.original)}</blockquote></div><div><span class="review-label">검증된 설명 / 조건 보완</span><p>${esc(r.verified)}</p></div></div><div class="review-ask"><b>강의 확인 필요</b><br>${esc(r.ask)}</div><a href="${r.url}" target="_blank" rel="noopener">검증 문서 열기 ↗</a></article>`).join(''):'<div class="note">이 페이지에는 별도 오류 후보를 등록하지 않았습니다. 원문 이미지와 해설을 비교해 읽으세요. 강의의 구두 보충 내용은 제공되지 않았습니다.</div>'}<div class="section-rule"><h3>전체 검토 목록 · ${R.length}개</h3><div class="topic-links">${R.map(r=>`<button data-review-id="${r.id}">${r.id.replace('-',' ')} · ${esc(r.kind)}</button>`).join('')}</div></div>`;$$('[data-review-id]').forEach(b=>b.onclick=()=>{const [u,n]=b.dataset.reviewId.split('-');go(u,+n,'review');});}
function next(delta){let index=L.indexOf(lesson());const l=L[index+delta];if(l)go(l.unit,l.page);}
$$('[data-unit]').forEach(b=>b.onclick=()=>{$('#search').value='';filter='all';go(b.dataset.unit,1);});$$('[data-tab]').forEach((b,i)=>{b.onclick=()=>{stop();tab=b.dataset.tab;render();};b.onkeydown=e=>{if(['ArrowRight','ArrowLeft'].includes(e.key)){e.preventDefault();const buttons=$$('[data-tab]'),j=(i+(e.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length;buttons[j].click();buttons[j].focus();}};});$('#search').oninput=renderNav;['all','wrong','review'].forEach(f=>$(`#${f}-filter`).onclick=()=>{filter=f;renderNav();});$('#prev').onclick=()=>next(-1);$('#next').onclick=$('#next-bottom').onclick=()=>next(1);$('#jump').onchange=e=>go(unit,+e.target.value);$('#complete').onclick=()=>{const id=lesson().id;saved.done=saved.done.includes(id)?saved.done.filter(x=>x!==id):[...saved.done,id];render();};$('#menu').onclick=()=>{document.body.classList.toggle('menu-open');$('#menu').setAttribute('aria-expanded',document.body.classList.contains('menu-open'));};$('#close-dialog').onclick=()=>$('#image-dialog').close();$('#image-dialog').onclick=e=>{if(e.target===$('#image-dialog'))$('#image-dialog').close();};$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({version:1,...saved},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='unix-lab-learning.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),5000);};$('#import').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2000000)throw Error();const d=JSON.parse(await f.text());if(!Array.isArray(d.done)||!d.answers||typeof d.answers!=='object')throw Error();const answers={};for(const [k,v]of Object.entries(d.answers)){if(validId(k)&&v&&Number.isInteger(v.choice)&&v.choice>=0&&v.choice<4&&typeof v.correct==='boolean'){const l=L.find(x=>x.id===k);answers[k]={choice:v.choice,correct:optionsFor(l)[v.choice].correct,attempts:Math.max(1,Math.min(100000,Number(v.attempts)||1))};}}const notes={};for(const[k,v]of Object.entries(d.notes||{})){if(validId(k)&&typeof v==='string')notes[k]=v.slice(0,20000);}saved={done:[...new Set(d.done.filter(validId))],answers,notes};render();toast('학습 기록을 불러왔습니다.');}catch(err){toast('올바른 학습 기록 JSON 파일을 선택하세요.');}e.target.value='';};
let parts=location.hash.slice(1).split('/');if(parts.length>=2&&L.some(x=>x.unit===parts[0]&&x.page===+parts[1])){unit=parts[0];page=+parts[1];if(['learn','lab','quiz','review','original'].includes(parts[2]))tab=parts[2];}else if(saved.last&&L.some(x=>x.unit===saved.last.unit&&x.page===saved.last.page)){unit=saved.last.unit;page=saved.last.page;tab=['learn','lab','quiz','review','original'].includes(saved.last.tab)?saved.last.tab:'learn';}
simName=defaultScenario();if(/^#w\d+\/\d+/.test(location.hash)){render();setTimeout(()=>$('#pages .active')?.scrollIntoView({block:'center'}),20);}

$("#close-menu").onclick=()=>{document.body.classList.remove("menu-open");$("#menu").setAttribute("aria-expanded","false");$("#menu").focus();};

function deepHTML(l){if(l.unit!=="w06")return "";const d=window.DEEP_NOTES.find(x=>l.page>=x.from&&l.page<=x.to);return d?`<div class="section-rule deep-notes"><h3>${esc(d.title)}</h3><dl>${d.rows.map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join("")}</dl><p class="lab-note">같은 주제의 인접 페이지를 연결한 보충 해설입니다. 실제 강의의 구두 설명을 옮긴 내용은 아닙니다.</p></div>`:"";}

window.UnixReader={open:(u,n,t='learn')=>{if(!L.some(l=>l.unit===u&&l.page===n)){u='w01';n=1;}go(u,n,['learn','lab','quiz','review','original'].includes(t)?t:'learn');},pause:stop,stats:()=>{const wrong=L.filter(l=>saved.answers[l.id]&&!saved.answers[l.id].correct);return {done:saved.done.filter(validId),wrong,answers:Object.keys(saved.answers).filter(validId).length,correct:Object.entries(saved.answers).filter(([id,a])=>validId(id)&&a.correct).length,last:saved.last||null};}};
